// project initialization
namespace SpriteKind {
    export const Cow = SpriteKind.create()
}

let topDownView = false
info.setScore(0)

// project start
scene.setBackgroundImage(assets.image`3DbackgroundImage`)
tiles.setCurrentTilemap(assets.tilemap`hayMaze`)

let player = sprites.create(assets.image`playerSprite`, SpriteKind.Player)
player.setKind(SpriteKind.Player)
tiles.placeOnTile(player, tiles.getTileLocation(1, 1))

game.onUpdateInterval(2000, function () {
    let cow = sprites.create(assets.image`cowImage`, SpriteKind.Cow)
    cow.lifespan = randint(3000, 7000)
    tiles.placeOnTile(cow, tiles.getTileLocation(randint(0, 16), randint(0, 16)))
})

// project events
controller.A.onEvent(ControllerButtonEvent.Pressed, function () {
    if (!topDownView) {
        topDownView = true
        scene.setBackgroundImage(assets.image`2DbackgroundImage`)
    }
    else if (topDownView) {
        topDownView = false
        scene.setBackgroundImage(assets.image`2DbackgroundImage`)
    }
})

sprites.onOverlap(SpriteKind.Player, SpriteKind.Cow, function (sprite: Sprite, otherSprite: Sprite) {
    sprites.destroy(otherSprite, effects.warmRadial)
    info.changeScoreBy(1)
})

scene.onOverlapTile(SpriteKind.Cow, assets.tile`hayTile`, function (sprite: Sprite, location: tiles.Location) {
    tiles.placeOnTile(sprite, tiles.getTileLocation(randint(0, 16), randint(0, 16)))
})

